-- | Monomial orderings supported for multivariate polynomial leading-term selection. Lex: pure lexicographic (variable 0 dominates). Grlex: total degree first, then lexicographic to break ties. Grevlex: total degree first, then REVERSE lexicographic (smallest trailing-variable exponent wins) to break ties -- the usual default for Groebner basis computations since it tends to keep intermediate polynomials smaller than Grlex.
--
-- Its constructors cross to C++ by name; 'R.enumValue' and 'R.enumFromValue' give the C++ values.
data MonomialOrder
  = MonomialOrderLex  -- ^ C++ @Lex@ (0).
  | MonomialOrderGrlex  -- ^ C++ @Grlex@ (1).
  | MonomialOrderGrevlex  -- ^ C++ @Grevlex@ (2).
  deriving (P.Eq, P.Ord, P.Show, P.Read, P.Bounded, P.Enum)

instance R.CppEnum MonomialOrder where
  enumValue _x = case _x of
    MonomialOrderLex -> 0
    MonomialOrderGrlex -> 1
    MonomialOrderGrevlex -> 2
  enumName _x = case _x of
    MonomialOrderLex -> "Lex"
    MonomialOrderGrlex -> "Grlex"
    MonomialOrderGrevlex -> "Grevlex"
  enumAll = [MonomialOrderLex, MonomialOrderGrlex, MonomialOrderGrevlex]
instance R.ToCpp MonomialOrder where toCpp = R.enumToCpp
instance R.FromCpp MonomialOrder where fromCpp = R.enumFromCpp

