-- | Linear-system method used by the spline least-squares fits.
--
-- Every fit forms symmetric normal equations (B^T B + P) c = B^T y. Cholesky is exact but costs O(K^3) for K unknowns; conjugate gradient on the sparse system costs roughly O(nnz) per iteration and suits large, well-conditioned (usually penalized) systems.
--
-- __Example__
--
-- > dm::fda::SplineSolveOptions options{dm::fda::SplineSolver::ConjugateGradient};
--
-- Its constructors cross to C++ by name; 'R.enumValue' and 'R.enumFromValue' give the C++ values.
data SplineSolver
  = SplineSolverAutomatic  -- ^ C++ @Automatic@ (0).
  | SplineSolverCholesky  -- ^ C++ @Cholesky@ (1).
  | SplineSolverConjugateGradient  -- ^ C++ @ConjugateGradient@ (2).
  deriving (P.Eq, P.Ord, P.Show, P.Read, P.Bounded, P.Enum)

instance R.CppEnum SplineSolver where
  enumValue _x = case _x of
    SplineSolverAutomatic -> 0
    SplineSolverCholesky -> 1
    SplineSolverConjugateGradient -> 2
  enumName _x = case _x of
    SplineSolverAutomatic -> "Automatic"
    SplineSolverCholesky -> "Cholesky"
    SplineSolverConjugateGradient -> "ConjugateGradient"
  enumAll = [SplineSolverAutomatic, SplineSolverCholesky, SplineSolverConjugateGradient]
instance R.ToCpp SplineSolver where toCpp = R.enumToCpp
instance R.FromCpp SplineSolver where fromCpp = R.enumFromCpp

