-- | Selected predecessor of an actual positive DTW cell. advance\_a changes the first coordinate, advance\_b the second. Finite ties prefer diagonal, then advance\_a, then advance\_b. Unrepresentable accumulated costs have no finite predecessor witness; successful traceback never uses them.
--
-- __Example__
--
-- > const auto t=dm::geometry::dynamic_time_warping_trace({1},{1});
-- > std::print("{}\n",t.predecessors[0]==dm::geometry::DTWPredecessor::origin); // true
--
-- Its constructors cross to C++ by name; 'R.enumValue' and 'R.enumFromValue' give the C++ values.
data DtwPredecessor
  = DtwPredecessorOrigin  -- ^ C++ @origin@ (0).
  | DtwPredecessorDiagonal  -- ^ C++ @diagonal@ (1).
  | DtwPredecessorAdvanceA  -- ^ C++ @advance\_a@ (2).
  | DtwPredecessorAdvanceB  -- ^ C++ @advance\_b@ (3).
  | DtwPredecessorUnrepresentable  -- ^ C++ @unrepresentable@ (4).
  deriving (P.Eq, P.Ord, P.Show, P.Read, P.Bounded, P.Enum)

instance R.CppEnum DtwPredecessor where
  enumValue _x = case _x of
    DtwPredecessorOrigin -> 0
    DtwPredecessorDiagonal -> 1
    DtwPredecessorAdvanceA -> 2
    DtwPredecessorAdvanceB -> 3
    DtwPredecessorUnrepresentable -> 4
  enumName _x = case _x of
    DtwPredecessorOrigin -> "origin"
    DtwPredecessorDiagonal -> "diagonal"
    DtwPredecessorAdvanceA -> "advance_a"
    DtwPredecessorAdvanceB -> "advance_b"
    DtwPredecessorUnrepresentable -> "unrepresentable"
  enumAll = [DtwPredecessorOrigin, DtwPredecessorDiagonal, DtwPredecessorAdvanceA, DtwPredecessorAdvanceB, DtwPredecessorUnrepresentable]
instance R.ToCpp DtwPredecessor where toCpp = R.enumToCpp
instance R.FromCpp DtwPredecessor where fromCpp = R.enumFromCpp

