-- > const auto t=dm::stats::t_test_one_sample({1,2,3,4},0,a);
-- > std::print("{}\n",t.alternative==a); // true
--
-- __References__
--
-- * https:\/\/stat.ethz.ch\/R-manual\/R-devel\/library\/stats\/html\/t.test.html
--
-- Its constructors cross to C++ by name; 'R.enumValue' and 'R.enumFromValue' give the C++ values.
data Alternative
  = AlternativeTwoSided  -- ^ C++ @TwoSided@ (0).
  | AlternativeLess  -- ^ C++ @Less@ (1).
  | AlternativeGreater  -- ^ C++ @Greater@ (2).
  deriving (P.Eq, P.Ord, P.Show, P.Read, P.Bounded, P.Enum)

instance R.CppEnum Alternative where
  enumValue _x = case _x of
    AlternativeTwoSided -> 0
    AlternativeLess -> 1
    AlternativeGreater -> 2
  enumName _x = case _x of
    AlternativeTwoSided -> "TwoSided"
    AlternativeLess -> "Less"
    AlternativeGreater -> "Greater"
  enumAll = [AlternativeTwoSided, AlternativeLess, AlternativeGreater]
instance R.ToCpp Alternative where toCpp = R.enumToCpp
instance R.FromCpp Alternative where fromCpp = R.enumFromCpp

-- | Multiple-comparison p-value adjustment methods, matching R\'s p.adjust.methods. Bonferroni\/Holm\/Hochberg\/Hommel control the family-wise error rate (FWER); BH\/BY control the false discovery rate (FDR); None returns the p-values unchanged.
--
-- Its constructors cross to C++ by name; 'R.enumValue' and 'R.enumFromValue' give the C++ values.
data PAdjustMethod
  = PAdjustMethodBonferroni  -- ^ C++ @Bonferroni@ (0).
  | PAdjustMethodHolm  -- ^ C++ @Holm@ (1).
  | PAdjustMethodHochberg  -- ^ C++ @Hochberg@ (2).
  | PAdjustMethodHommel  -- ^ C++ @Hommel@ (3).
  | PAdjustMethodBh  -- ^ C++ @BH@ (4).
  | PAdjustMethodBy  -- ^ C++ @BY@ (5).
  | PAdjustMethodNone  -- ^ C++ @None@ (6).
  deriving (P.Eq, P.Ord, P.Show, P.Read, P.Bounded, P.Enum)

instance R.CppEnum PAdjustMethod where
