toCallback = R.wrapHandle P.. R.objectHandle

-- | Creates a Callback (C++ constructor).
--
-- C++: @datamunge::Callback::Callback()@
newCallback :: P.IO Callback
newCallback =
  P.fmap Callback' (R.construct 437 P.Nothing [])

-- | Haskell overrides of the virtual methods of 'Callback', for the @extendCallback@ functions: each field left 'P.Nothing' keeps the C++ implementation.
data CallbackOverrides = CallbackOverrides
  { callbackCallOverride :: P.Maybe (Callback -> P.Double -> P.IO P.Double)
    -- ^ Overrides virtual @double datamunge::Callback::call(double x)@.
  }

-- | No overrides: every virtual method runs its C++ implementation. Set the fields of the overrides to
-- implement: @callbackOverrides { ... }@.
callbackOverrides :: CallbackOverrides
callbackOverrides = CallbackOverrides { callbackCallOverride = P.Nothing }

-- | Creates an extended Callback: a C++ subclass object whose virtual methods run the given overrides.
--
-- C++ calls the overrides too, and an override's first argument is the object itself; the @...Base@ functions run the C++ implementation an override replaces. A pure virtual method without override throws a 'R.BindingError'.
--
-- C++: @datamunge::Callback::Callback()@
extendCallback
  :: CallbackOverrides  -- ^ the Haskell overrides (fields left 'P.Nothing' run the C++ implementation)
  -> P.IO Callback
extendCallback _overrides =
  P.fmap Callback' (R.construct 437 (P.Just (R.director
    [ ((13, 1), P.maybe (R.base 436) (\_f -> R.overrideWith (\_h -> _f (Callback' _h))) (callbackCallOverride _overrides))
    ])) [])

-- | Applies the callback to a single value.
--
-- Virtual: on an extended object (made by an @extend@ function) it runs the Haskell override.
--
-- C++: @double datamunge::Callback::call(double x)@
callbackCall
  :: IsCallback a
  => a  -- ^ the object
  -> P.Double  -- ^ Input value.
  -> P.IO P.Double  -- ^ Transformed value; the default implementation returns @x@ unchanged.
callbackCall _self _x1 = R.callVirtual 13 436 [R.object _self, R.toCpp _x1] P.>>= R.result

-- | Applies the callback to a single value.
--
-- Runs the C++ implementation even on an extended object: what an override calls for the behavior it replaces.
--
-- C++: @double datamunge::Callback::call(double x)@
callbackCallBase
  :: IsCallback a
  => a  -- ^ the object
  -> P.Double  -- ^ Input value.
  -> P.IO P.Double  -- ^ Transformed value; the default implementation returns @x@ unchanged.
callbackCallBase _self _x1 = R.call 436 [R.object _self, R.toCpp _x1] P.>>= R.result

