  => a  -- ^ the object
  -> P.Double  -- ^ y value at x = 0.
  -> P.Double  -- ^ Change in y per unit x.
  -> P.IO RPlot  -- ^ This plot, for chaining.
rPlotAbline _self _x1 _x2 = R.call 588 [R.object _self, R.toCpp _x1, R.toCpp _x2] P.>>= R.result

