toAcor = R.wrapHandle P.. R.objectHandle

-- | Creates a Acor (C++ constructor).
--
-- Arguments left out take the C++ defaults: @options@ = its C++ default.
--
-- C++: @datamunge::optim::ACOR::ACOR(ACOROptions options = {})@
newAcor :: P.IO Acor
newAcor =
  P.fmap Acor' (R.construct 1501 P.Nothing [])

-- | Creates a Acor (C++ constructor).
--
-- C++: @datamunge::optim::ACOR::ACOR(ACOROptions options = {})@
newAcorWithOptions :: IsAcorOptions a => a -> P.IO Acor
newAcorWithOptions _x1 =
  P.fmap Acor' (R.construct 1501 P.Nothing [R.object _x1])

-- | Minimizes @function@ within \[@lower\_bound@, @upper\_bound@\], updating @coordinates@ in place to the best point found, and returns its value. The initial @coordinates@ (clamped into bounds) seed one member of the archive.
--
-- C++: @double datamunge::optim::ACOR::optimize(ArbitraryFunction & function, std::vector\<double\> & coordinates, const std::vector\<double\> & lower\_bound, const std::vector\<double\> & upper\_bound) const@
acorOptimize
  :: (IsAcor a, IsArbitraryFunction b)
  => a  -- ^ the object
  -> b
  -> IORef.IORef [P.Double]  -- ^ C++ writes it back
  -> [P.Double]
  -> [P.Double]
  -> P.IO P.Double
acorOptimize _self _x1 _x2 _x3 _x4 = do
  _v2 <- IORef.readIORef _x2
  _reply <- R.call 1499 [R.object _self, R.object _x1, R.slot 0 _v2, R.toCpp _x3, R.toCpp _x4]
  R.writeBack _reply 0 _x2
  R.result _reply

