--
-- C++: @double datamunge::stats::ARIMA::mean() const@
arimaMean
  :: IsArima a
  => a  -- ^ the object
  -> P.IO P.Double  -- ^ The mean, or 0 when no mean term was fit (include\_mean is false, or d or D is nonzero).
arimaMean _self = R.call 2267 [R.object _self] P.>>= R.result

-- | Length of the input series.
--
-- C++: @std::size\_t datamunge::stats::ARIMA::observations() const@
arimaObservations
  :: IsArima a
  => a  -- ^ the object
  -> P.IO P.Int  -- ^ The number of observations passed to the constructor.
arimaObservations _self = R.call 2268 [R.object _self] P.>>= R.result

-- | Number of residuals that enter the sum of squares.
--
-- @p+sP@ (the conditioned-on presample).
--
-- C++: @std::size\_t datamunge::stats::ARIMA::n\_used() const@
arimaNUsed
  :: IsArima a
  => a  -- ^ the object
  -> P.IO P.Int  -- ^ The differenced series length minus
arimaNUsed _self = R.call 2269 [R.object _self] P.>>= R.result

-- | Innovation variance estimate.
--
-- C++: @double datamunge::stats::ARIMA::sigma2() const@
arimaSigma2
  :: IsArima a
  => a  -- ^ the object
  -> P.IO P.Double  -- ^ The CSS residual sum of squares divided by n\_used().
arimaSigma2 _self = R.call 2270 [R.object _self] P.>>= R.result

-- | Gaussian log-likelihood at the CSS estimate, over n\_used() residuals.
--
-- @-\\tfrac{n}{2}(\\log 2\\pi + \\log\\sigma^2 + 1)@ with @n@ = n\_used().
--
-- C++: @double datamunge::stats::ARIMA::log\_likelihood() const@
arimaLogLikelihood
  :: IsArima a
  => a  -- ^ the object
  -> P.IO P.Double
arimaLogLikelihood _self = R.call 2271 [R.object _self] P.>>= R.result

-- | Akaike information criterion.
--
-- @-2\\ell + 2k@, where @k@ counts the coefficients, the mean (if fit) and @\\sigma^2@.
--
-- C++: @double datamunge::stats::ARIMA::aic() const@
arimaAic
  :: IsArima a
  => a  -- ^ the object
  -> P.IO P.Double
arimaAic _self = R.call 2272 [R.object _self] P.>>= R.result

-- | Bayesian information criterion.
--
-- @-2\\ell + k\\log n@, with @k@ as in aic() and @n@ = n\_used().
--
-- C++: @double datamunge::stats::ARIMA::bic() const@
arimaBic
  :: IsArima a
  => a  -- ^ the object
  -> P.IO P.Double
arimaBic _self = R.call 2273 [R.object _self] P.>>= R.result

-- | One-step-ahead fitted values on the original scale, aligned to the input series (the first @observations() - n\_used()@ entries -- the presample points conditioned on by CSS -- are copies of the observed value, matching a residual of exactly zero there rather than an undefined value).
--
-- C++: @const std::vector\<double\> & datamunge::stats::ARIMA::fitted\_values() const@
arimaFittedValues
  :: IsArima a
  => a  -- ^ the object
  -> P.IO [P.Double]
arimaFittedValues _self = R.call 2274 [R.object _self] P.>>= R.result

-- | One-step-ahead residuals on the original scale (zero for the presample points).
--
-- C++: @const std::vector\<double\> & datamunge::stats::ARIMA::residuals() const@
arimaResiduals
  :: IsArima a
  => a  -- ^ the object
  -> P.IO [P.Double]
arimaResiduals _self = R.call 2275 [R.object _self] P.>>= R.result

-- | Point forecasts for the next @horizon@ periods, on the original scale.
--
-- C++: @std::vector\<double\> datamunge::stats::ARIMA::forecast(std::size\_t horizon) const@
arimaForecast
  :: IsArima a
  => a  -- ^ the object
  -> P.Int  -- ^ Number of steps ahead to forecast.
  -> P.IO [P.Double]  -- ^ A vector of length @horizon@ (empty when @horizon@ is 0).
arimaForecast _self _x1 = R.call 2276 [R.object _self, R.toCpp _x1] P.>>= R.result

-- | AR coefficients of the stationary (differenced) model after multiplying the regular and seasonal polynomials,
--
-- @w\_t=\\sum\_i a\_i w\_{t-i}+\\varepsilon\_t+\\sum\_j b\_j\\varepsilon\_{t-j}@.
--
-- @a\_i@, @i=1,\\dots,p+sP@ (zeros where no lag enters).
--
-- C++: @const std::vector\<double\> & datamunge::stats::ARIMA::expanded\_ar\_coefficients() const@
arimaExpandedArCoefficients
  :: IsArima a
  => a  -- ^ the object
  -> P.IO [P.Double]  -- ^ The
arimaExpandedArCoefficients _self = R.call 2277 [R.object _self] P.>>= R.result

-- | MA coefficients
--
-- @b\_j@ of the stationary model, after multiplying the regular and seasonal MA polynomials; for the airline model @(\\theta,0,\\dots,0,\\Theta,\\theta\\Theta)@.
--
-- @b\_j@, @j=1,\\dots,q+sQ@.
--
-- C++: @const std::vector\<double\> & datamunge::stats::ARIMA::expanded\_ma\_coefficients() const@
arimaExpandedMaCoefficients
  :: IsArima a
  => a  -- ^ the object
  -> P.IO [P.Double]  -- ^ The
arimaExpandedMaCoefficients _self = R.call 2278 [R.object _self] P.>>= R.result

-- | The first @count@
--
-- @\\psi@-weights of the full model, differencing included: @y\_t=\\sum\_{j\\ge0}\\psi\_j\\varepsilon\_{t-j}@ formally, with @\\psi\_0=1@.
--
-- The h-step forecast error is @\\sum\_{j\<h}\\psi\_j\\varepsilon\_{t+h-j}@, so its variance is @\\sigma^2\\sum\_{j\<h}\\psi\_j^2@; forecast\_with\_intervals() uses exactly these weights.
--
-- @\\psi\_0,\\dots,\\psi\_{count-1}@.
--
-- C++: @std::vector\<double\> datamunge::stats::ARIMA::psi\_weights(std::size\_t count) const@
arimaPsiWeights
  :: IsArima a
  => a  -- ^ the object
  -> P.Int  -- ^ Number of weights.
  -> P.IO [P.Double]
arimaPsiWeights _self _x1 = R.call 2279 [R.object _self, R.toCpp _x1] P.>>= R.result

-- | Point forecasts and their standard errors (from the psi-weight \/ MA(infinity) expansion of the full, non-stationary AR\/MA representation of y), on the original scale.
--
-- C++: @std::pair\<std::vector\<double\>, std::vector\<double\>\> datamunge::stats::ARIMA::forecast\_with\_intervals(std::size\_t horizon) const@
arimaForecastWithIntervals
  :: IsArima a
  => a  -- ^ the object
  -> P.Int  -- ^ Number of steps ahead to forecast.
  -> P.IO ([P.Double], [P.Double])  -- ^ A pair (point forecasts, standard errors), each of length @horizon@.
arimaForecastWithIntervals _self _x1 = R.call 2280 [R.object _self, R.toCpp _x1] P.>>= R.result

