-- The C++ class @datamunge::DataFrame@.
--
-- A value holds the C++ object; it is released when garbage collection reclaims the last value holding it, or by 'R.closeObject'.
newtype DataFrame = DataFrame' R.Handle

instance R.CppObject DataFrame where
  objectHandle (DataFrame' _h) = _h
  wrapHandle = DataFrame'
  classIndex _ = 231
instance R.ToCpp DataFrame where toCpp = R.object
instance R.FromCpp DataFrame where fromCpp = R.fromObject

-- | Values of class 'DataFrame', or of a class deriving from it.
class R.CppObject a => IsDataFrame a
instance IsDataFrame DataFrame

