-- | SWIG-friendly facade for datamunge::stats::LM — R-@lm()@-style linear models fit from a DataFrame.
--
-- The C++ class @datamunge::LM@.
--
-- A value holds the C++ object; it is released when garbage collection reclaims the last value holding it, or by 'R.closeObject'.
newtype Lm = Lm' R.Handle

instance R.CppObject Lm where
  objectHandle (Lm' _h) = _h
  wrapHandle = Lm'
  classIndex _ = 236
instance R.ToCpp Lm where toCpp = R.object
instance R.FromCpp Lm where fromCpp = R.fromObject

-- | Values of class 'Lm', or of a class deriving from it.
class R.CppObject a => IsLm a
instance IsLm Lm

-- | The object as a 'Lm' (an upcast).
