-- ---------------------------------------------------------------- Lda

-- | SWIG-friendly facade for datamunge::stats::LDA — R-@MASS::lda()@-style linear discriminant analysis.
--
-- The C++ class @datamunge::LDA@.
--
-- A value holds the C++ object; it is released when garbage collection reclaims the last value holding it, or by 'R.closeObject'.
newtype Lda = Lda' R.Handle

instance R.CppObject Lda where
  objectHandle (Lda' _h) = _h
  wrapHandle = Lda'
  classIndex _ = 240
instance R.ToCpp Lda where toCpp = R.object
instance R.FromCpp Lda where fromCpp = R.fromObject

-- | Values of class 'Lda', or of a class deriving from it.
class R.CppObject a => IsLda a
instance IsLda Lda

-- | The object as a 'Lda' (an upcast).
toLda :: IsLda a => a -> Lda
toLda = R.wrapHandle P.. R.objectHandle

-- | Creates a Lda (C++ constructor).
--
-- Arguments left out take the C++ defaults: @priors@ = its C++ default.
--
-- C++: @datamunge::LDA::LDA(const DataFrame & data, const std::string & formula, const std::vector\<double\> & priors = {})@
newLda :: IsDataFrame a => a -> P.String -> P.IO Lda
newLda _x1 _x2 =
  P.fmap Lda' (R.construct 2644 P.Nothing [R.object _x1, R.toCpp _x2])

