-- ---------------------------------------------------------------- CadScene

-- | A small code-driven scene facade, exposed as CadScene in Python\/R. Owns scene\/camera\/render controls. All operations delegate to the canonical CAD, polygon and renderer APIs; copying retains independent scene state.
--
-- __Example__
--
-- > dm::cad::View view;
-- > view.add(dm::cad::Solid::box(2, 3, 4), "#3b82f6", "block");
-- > view.size(640, 480); view.render("block.png");
--
-- The C++ class @datamunge::cad::View@.
--
-- A value holds the C++ object; it is released when garbage collection reclaims the last value holding it, or by 'R.closeObject'.
newtype CadScene = CadScene' R.Handle

instance R.CppObject CadScene where
  objectHandle (CadScene' _h) = _h
  wrapHandle = CadScene'
  classIndex _ = 279
instance R.ToCpp CadScene where toCpp = R.object
instance R.FromCpp CadScene where fromCpp = R.fromObject

-- | Values of class 'CadScene', or of a class deriving from it.
class R.CppObject a => IsCadScene a
instance IsCadScene CadScene

-- | The object as a 'CadScene' (an upcast).
toCadScene :: IsCadScene a => a -> CadScene
toCadScene = R.wrapHandle P.. R.objectHandle

-- | Create an empty scene with automatic camera framing.
--
-- __Example__
--
-- See the class example.
--
-- C++: @datamunge::cad::View::View()@
newCadScene :: P.IO CadScene
newCadScene =
  P.fmap CadScene' (R.construct 3314 P.Nothing [])

