  classIndex _ = 281
instance R.ToCpp BSplineRefinement where toCpp = R.object
instance R.FromCpp BSplineRefinement where fromCpp = R.fromObject

-- | Values of class 'BSplineRefinement', or of a class deriving from it.
class R.CppObject a => IsBSplineRefinement a
instance IsBSplineRefinement BSplineRefinement

-- | The object as a 'BSplineRefinement' (an upcast).
toBSplineRefinement :: IsBSplineRefinement a => a -> BSplineRefinement
toBSplineRefinement = R.wrapHandle P.. R.objectHandle

