newBSplineRefinement =
  P.fmap BSplineRefinement' (R.construct 3327 P.Nothing [])

-- | Maps coarse coefficients to the refined basis.
--
-- __Example__
--
-- > auto r = dm::fda::dyadic_refine(dm::fda::BSplineBasis::open_uniform(1, 2));
-- > std::print("{}\n", r.apply({0.0, 2.0})); // [0, 1, 2]
--
-- C++: @std::vector\<double\> datamunge::fda::BSplineRefinement::apply(const std::vector\<double\> & coefficients) const@
--
-- Throws t'R.CppError' ('R.InvalidArgument') for C++ @std::invalid\_argument@: If @coefficients@ does not match the coarse basis size.
bSplineRefinementApply
  :: IsBSplineRefinement a
  => a  -- ^ the object
  -> [P.Double]  -- ^ One coefficient per coarse basis function.
  -> P.IO [P.Double]  -- ^ One coefficient per refined basis function, representing the same spline.
bSplineRefinementApply _self _x1 = R.call 3324 [R.object _self, R.toCpp _x1] P.>>= R.result

