bSplineRefinementSetBasis _self _x = R.call 3326 [R.object _self, R.object _x] P.>>= R.result

-- ---------------------------------------------------------------- TensorBSpline

-- | A scalar tensor-product B-spline f(x) = sum\_j c\_j B\_j(x) with owned coefficients.
--
-- With one basis this is an ordinary spline curve; with d bases a surface or volume. The coefficient net is row-major over the per-axis basis sizes (last axis fastest), the same column order as fda::BSpline::evaluate(). Evaluation clamps each coordinate into the basis domain, so points outside the domain take the boundary value. Const methods are safe to call concurrently while the object is not mutated.
--
-- __Example__
--
-- > auto b = dm::fda::BSplineBasis::open_uniform(1, 2);     // linear on [0, 1]
-- > dm::fda::TensorBSpline f({b, b}, {0, 1, 1, 2});         // f(x, y) = x + y
-- > std::print("{:.2f}\n", f.evaluate({0.25, 0.5}));        // 0.75
--
-- __References__
--
-- * C. de Boor (1972). On calculating with B-splines. Journal of Approximation Theory 6(1), 50-62. https:\/\/doi.org\/10.1016\/0021-9045(72)90080-9
--
-- The C++ class @datamunge::fda::TensorBSpline@.
--
-- A value holds the C++ object; it is released when garbage collection reclaims the last value holding it, or by 'R.closeObject'.
newtype TensorBSpline = TensorBSpline' R.Handle

instance R.CppObject TensorBSpline where
  objectHandle (TensorBSpline' _h) = _h
  wrapHandle = TensorBSpline'
  classIndex _ = 282
instance R.ToCpp TensorBSpline where toCpp = R.object
instance R.FromCpp TensorBSpline where fromCpp = R.fromObject

-- | Values of class 'TensorBSpline', or of a class deriving from it.
class R.CppObject a => IsTensorBSpline a
instance IsTensorBSpline TensorBSpline

-- | The object as a 'TensorBSpline' (an upcast).
toTensorBSpline :: IsTensorBSpline a => a -> TensorBSpline
toTensorBSpline = R.wrapHandle P.. R.objectHandle

