-- | The C++ class @datamunge::nn::NnTensor@.
--
-- A value holds the C++ object; it is released when garbage collection reclaims the last value holding it, or by 'R.closeObject'.
newtype NnTensor = NnTensor' R.Handle

instance R.CppObject NnTensor where
  objectHandle (NnTensor' _h) = _h
  wrapHandle = NnTensor'
  classIndex _ = 287
instance R.ToCpp NnTensor where toCpp = R.object
instance R.FromCpp NnTensor where fromCpp = R.fromObject

-- | Values of class 'NnTensor', or of a class deriving from it.
class R.CppObject a => IsNnTensor a
instance IsNnTensor NnTensor

-- | The object as a 'NnTensor' (an upcast).
